    with pytest.raises(ZeroDivisionError, match="No se puede dividir"):
        dividir(10, 0)

def test_division_negativa():
    assert dividir(-6, 2) == -3.0

def test_division_flotante():
    assert pytest.approx(dividir(1, 3)) == 0.333, 0.001

